    const button = event.target.closest?.('[data-shiyu-login]');
    if (!button) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    if (!button.dataset.accountHandled) {
      button.dataset.accountHandled = 'true';
      void login(button);
    }
