  list.classList.add('search-engine-tabs-list');
  list.innerHTML=`<div class="search-engine-tabs-nav" role="tablist">${groups.map((group,i)=>`<button type="button" role="tab" aria-selected="${i===0}" data-engine-tab="${i}">${group.querySelector('.search-engine-heading')?.textContent||"Search"}</button>`).join('')}</div><div class="search-engine-tab-panels">${groups.map((group,i)=>`<section class="search-engine-tab-panel" role="tabpanel" data-engine-panel="${i}" ${i?'hidden':''}><label class="search-engine-filter"><span aria-hidden="true">⌕</span><input type="search" placeholder="搜索${group.querySelector('.search-engine-heading')?.textContent||"引擎"}" aria-label="搜索${group.querySelector('.search-engine-heading')?.textContent||"引擎"}"></label><div class="search-engine-options">${[...group.querySelectorAll('button[data-value]')].map(button=>{const id=button.dataset.value,label=button.firstChild?.textContent?.trim()||button.textContent.trim();return `<button type="button" role="option" aria-selected="${button.getAttribute('aria-selected')==='true'}" data-value="${esc(id)}"><img class="search-engine-logo" src="https://cdn.simpleicons.org/${slug(id)}" alt="" aria-hidden="true" onerror="this.hidden=true"><span>${esc(label)}</span>${button.getAttribute('aria-selected')==='true'?'<b aria-hidden="true">✓</b>':''}</button>`}).join('')}</div></section>`).join('')}</div>`;
  list.querySelectorAll('.search-engine-filter,.search-engine-logo').forEach(node=>node.remove());
  const preferred=typeof defaultSearchEngine==='function'?defaultSearchEngine():'baidu';
  const primary=list.querySelector('[data-engine-panel="0"] .search-engine-options'),first=primary?.querySelector('[data-value="'+preferred+'"]');
  if(first)primary.prepend(first);
  list.querySelectorAll('[data-engine-tab]').forEach(tab=>tab.onclick=()=>{const index=tab.dataset.engineTab;list.querySelectorAll('[data-engine-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===tab)));list.querySelectorAll('[data-engine-panel]').forEach(panel=>panel.hidden=panel.dataset.enginePanel!==index)});
 }
