// Unified account dialog: keep the costlier phone path last, and make the
// password path determine registration state before submitting credentials.
(()=>{
  accountLoginTab='password';
  const validPhone=value=>/^1\d{10}$/.test(value);
  const validEmail=value=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value).trim());
  const cloneValue=value=>JSON.parse(JSON.stringify(value));
  const clearLoginPrefill=d=>{
    const clear=()=>d.querySelectorAll('[data-login-account],[data-login-credential]').forEach(input=>{input.value='';input.removeAttribute('value')});
    clear();
    requestAnimationFrame(()=>{clear();setTimeout(clear,80)});
  };
  const accountMessage=(d,text,field)=>{d.querySelectorAll('.account-field-error').forEach(error=>{error.textContent=''});const status=d.querySelector('.account-status');if(status)status.textContent=field?'':text;if(field){const error=d.querySelector('.account-field-error[data-error-for="'+field+'"]');if(error)error.textContent=text;}};
  const loginErrorField=text=>/验证码|密码|凭证|登录方式/.test(String(text||''))?'credential':'account';
  const syncServerAccount=(result)=>{
    if(window.ShiyuAccountSession){window.ShiyuAccountSession.applyLogin(result);return;}
    signed=true;
    prefs.accountProfile={...(prefs.accountProfile||{}),id:result.user.id,name:result.user.name,phone:result.user.phone,email:result.user.email,avatar:prefs.accountProfile?.avatar||ACCOUNT_AVATARS[0]};
    prefs.membership=result.user.member?{...result.user.membership,label:result.user.membership?.permanent?"永久":result.user.memberExpiresAt||''}:null;
    prefs.accountDataUserId=result.user.id;
    if(Array.isArray(result.accountData))data=cloneValue(result.accountData);
    persist();
    window.dispatchEvent(new CustomEvent('shiyu-account-state',{detail:result}));
  };
  async function submitAccount(button){
    const d=$('#login'), account=d.querySelector('[data-login-account]')?.value.trim()||'', credentialInput=d.querySelector('[data-login-credential]')?.value||'', emailMode=accountLoginTab==='email'||d.querySelector('[data-account-tab=email][aria-selected=true],[data-account-tab=email][aria-pressed=true]')!==null;
    // Determine the request mode from the button that was clicked. The dialog
    // can be re-rendered by the tab switcher, so the global tab value is not a
    // reliable source at submit time.
    const codeMode=button?.hasAttribute('data-code-submit')===true;
    const credential=codeMode?credentialInput.replace(/\s+/g,''):credentialInput.trim();
    if(!codeMode){
      if(!validPhone(account)&&!validEmail(account)){accountMessage(d,"请输入正确的邮箱或手机号",'account');return;}
      if(!credential){accountMessage(d,"Enter password",'credential');return;}
    }else{
      if(emailMode?!validEmail(account):!validPhone(account)){accountMessage(d,emailMode?"请输入正确的邮箱地址":"请输入 11 位数字的手机号",'account');return;}
      if(!/^\d{4,8}$/.test(credential)){accountMessage(d,"请输入正确位数的验证码",'credential');return;}
    }
    // Guard against a second listener or a rapid second click submitting the
    // same one-time code while the first request is still in flight.
    if(button?.dataset.submitting==='1')return;
    if(button)button.dataset.submitting='1';
    button.disabled=true;accountMessage(d,"Signing in…");
    try{
      const payload={account,credential,mode:codeMode?'code':'password',invitationCode:window.shiyuInvitationCode||sessionStorage.getItem('shiyu-invitation-code')||undefined};
      const result=await window.ShiyuAccountSession.login(payload);
      const needsProfile=!profileBasicsComplete(prefs.accountProfile);
      const successText="已与你相识，欢迎来到拾隅。";
      syncServerAccount(result);d.close();render();
      if(needsProfile&&!organizationAfterLogin&&!pending)openAccountCenter();
      setTimeout(()=>toast(successText),0);
    }catch(error){const message=error.message||"Sign-In Failed";accountMessage(d,message,loginErrorField(message))}finally{if(button){button.disabled=false;delete button.dataset.submitting;}}
  }
  function openWechatBindForm(d){
    d.innerHTML="<div class=\"dialog-heading\"><h2>绑定邮箱</h2><button data-wechat-close aria-label=\"Close\">×</button></div><p class=\"account-note\">绑定邮箱后，下次可以使用邮箱或微信等多种方式登录，进入账号会更方便。</p><label>Email<input data-wechat-email type=\"email\" autocomplete=\"off\" placeholder=\"name@example.com\"></label><label>Email Code<div class=\"account-input-row\"><input data-wechat-code inputmode=\"numeric\" maxlength=\"6\" placeholder=\"Enter code\"><button data-wechat-code-send disabled>Send Code</button></div></label><label>设置密码<input data-wechat-password type=\"password\" autocomplete=\"new-password\" placeholder=\"8–20 位，至少两类字符\"></label><label>Confirm Password<input data-wechat-confirm type=\"password\" autocomplete=\"new-password\" placeholder=\"Enter password again\"></label><p class=\"account-status\" role=\"status\">请先填写邮箱，再获取验证码。</p><button class=\"primary full\" data-wechat-bind>绑定并登录</button>";
    d.querySelector('[data-wechat-close]').onclick=()=>d.close();
    const email=d.querySelector('[data-wechat-email]'),send=d.querySelector('[data-wechat-code-send]');
    const sync=()=>{const ready=validEmail(email.value);send.disabled=!ready;send.classList.toggle('is-ready',ready)};email.addEventListener('input',sync);sync();
    send.onclick=()=>accountMessage(d,"验证码服务正在接入阿里云安全防刷验证");
    d.querySelector('[data-wechat-bind]').onclick=()=>{const value=email.value.trim(),p=d.querySelector('[data-wechat-password]').value,c=d.querySelector('[data-wechat-confirm]').value;if(!validEmail(value)){accountMessage(d,"请输入主流邮箱地址");return}if(!p||p!==c){accountMessage(d,"请填写密码，且两次输入必须一致");return}accountMessage(d,"微信绑定接口待接入");};
  }
  function openWechatBind(){
    let d=$('#wechat-bind-flow');if(!d){d=document.createElement('dialog');d.id='wechat-bind-flow';document.body.append(d)}
    d.innerHTML="<div class=\"dialog-heading\"><h2>Sign in with WeChat</h2><button data-wechat-close aria-label=\"Close\">×</button></div><div class=\"wechat-qr-placeholder\" aria-label=\"微信登录二维码\"><span>微信二维码</span></div><p class=\"account-note wechat-scan-status\" role=\"status\">请使用微信扫描二维码，扫码确认后再继续。</p><p class=\"account-note\">正在等待微信服务号返回登录结果。</p>";
    d.querySelector('[data-wechat-close]').onclick=()=>d.close();d.showModal();
    // The real service号 callback can call this after scan confirmation.
    window.ShiyuWechatLogin={complete(){if(!d.open)return;openWechatBindForm(d);}};
  }
  renderAccountLogin=function(){
    const d=$('#login'),tab=accountLoginTab;d.innerHTML="<div class=\"dialog-heading\"><div><span class=\"eyebrow\">NOOK</span><h2>Welcome to <span class=\"login-brand-name\">Shiyu</span></h2></div><button data-action=\"close\" aria-label=\"Close Sign In\">×</button></div><p class=\"account-note\">登录后，收藏与个性设置会保存在你的账号下。</p><div class=\"settings-tabs\">"+[['password',"Password"],['email',"Email"],['phone',"手机登录"]].map(([id,n])=>'<button data-account-tab="'+id+'" aria-selected="'+(tab===id)+'">'+n+'</button>').join('')+'</div><div class="account-login-content">'+(tab==='password'?"<label><span class=\"account-field-caption\">邮箱/手机号</span><input data-login-account autocomplete=\"username\" readonly placeholder=\"请输入邮箱或手机号\"></label><label><span class=\"account-field-caption\">Password</span><input data-login-credential type=\"password\" autocomplete=\"current-password\" readonly placeholder=\"Enter password\"></label><button class=\"primary full\" data-login-submit-v2>登录/注册</button>": '<label><span class="account-field-caption">'+(tab==='email'?"Email":"Phone")+'</span>'+(tab==='phone'?"<div class=\"account-country-input\"><span>+86</span><input data-login-account autocomplete=\"tel\" readonly inputmode=\"tel\" maxlength=\"11\" pattern=\"[0-9]{11}\" placeholder=\"Enter phone number\"></div>":'<input data-login-account type="email" autocomplete="email" readonly inputmode="email" placeholder="name@example.com">')+"</label><label><span class=\"account-field-caption\">Code</span><div class=\"account-input-row\"><input data-login-credential autocomplete=\"one-time-code\" maxlength=\"8\" placeholder=\"Enter code\"><button data-code-send disabled>Send Code</button></div></label><button class=\"primary full\" data-code-submit>登录/注册</button>")+"</div><div class=\"account-third-party\"><button data-wechat-login aria-label=\"微信登录\">"+ACCOUNT_WECHAT_SVG+'</button></div><p class="account-status" role="status"></p>';
    decorateAccountLogin();
    d.querySelectorAll('.account-login-content>label').forEach((label,index)=>{const error=document.createElement('small');error.className='account-field-error';error.dataset.errorFor=index===0?'account':'credential';error.setAttribute('role','alert');label.after(error)});
    clearLoginPrefill(d);
    d.querySelectorAll('[data-login-account],[data-login-credential]').forEach(input=>{
      input.addEventListener('focus',()=>input.removeAttribute('readonly'),{once:true});
      input.addEventListener('input',()=>{const field=input.hasAttribute('data-login-account')?'account':'credential',error=d.querySelector('.account-field-error[data-error-for="'+field+'"]');if(error)error.textContent=''});
    });
    const status=d.querySelector('.account-status');if(status)status.textContent='';
    d.querySelector('[data-login-submit-v2]')?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();void submitAccount(e.currentTarget)});
    const accountInput=d.querySelector('[data-login-account]'),codeSend=d.querySelector('[data-code-send]');
    if(codeSend&&accountInput){const syncCodeState=()=>{const ready=tab==='email'?validEmail(accountInput.value):validPhone(accountInput.value);codeSend.disabled=!ready;codeSend.classList.toggle('is-ready',ready)};if(tab==='phone')accountInput.addEventListener('paste',event=>{const text=event.clipboardData?.getData('text')||'';if(/\D/.test(text)){event.preventDefault();accountInput.value=text;syncCodeState()}});accountInput.addEventListener('input',syncCodeState);syncCodeState();}
    codeSend?.addEventListener('click',async()=>{
      const account=accountInput?.value.trim()||'',emailMode=tab==='email';
      if(emailMode?!validEmail(account):!validPhone(account)){accountMessage(d,emailMode?"请输入正确的邮箱地址":"请输入 11 位数字的手机号",'account');return}
      codeSend.disabled=true;accountMessage(d,"正在发送验证码…");
      try{
        const response=await fetch(emailMode?'/api/shiyu/auth/email/send':'/api/shiyu/auth/send-code',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(emailMode?{email:account.toLowerCase(),purpose:'login'}:{phone:account,purpose:'login'})});
        const raw=await response.text();let result={};try{result=raw?JSON.parse(raw):{}}catch{result={}}
        if(!response.ok)throw new Error(result.message||(emailMode?"邮件发送失败":"短信发送失败"));
        let left=60;codeSend.textContent=left+"秒后重试";const timer=setInterval(()=>{left-=1;if(left<=0){clearInterval(timer);codeSend.disabled=false;codeSend.textContent="Send Code"}else codeSend.textContent=left+"秒后重试"},1000);
        accountMessage(d,"验证码已发送，"+Math.round(Number(result.expiresIn||600)/60)+"分钟内有效。");
      }catch(error){
        codeSend.disabled=false;const message=String(error?.message||'');
        const unavailable=/JSON|Unexpected|Failed to execute|Failed to fetch|Load failed|NetworkError|Network request failed|request\.validate/i.test(message);
        const errorText=unavailable?(emailMode?"邮件服务暂时不可用，请稍后再试":"短信服务暂时不可用，请稍后再试"):message||(emailMode?"邮件发送失败":"短信发送失败");
        accountMessage(d,errorText,'account');
      }
    });
    d.querySelector('[data-code-submit]')?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();void submitAccount(e.currentTarget)});
  };
  renderAccountLogin();
})();

