 const empty={world:{enabled:false,audience:'all',percentage:100,whitelist:'',blacklist:'',title:"一个值得慢慢探索的世界",description:"发现精选网址、学习路线与创作素材，遇见更多值得收藏的灵感。"},announcement:{enabled:false},update:{enabled:false}};
 let config=empty,identity='',previewKind='',dialog,timer,loadingPublished,previewReceived=false;
 const lists=value=>String(value||'').split(/[\s,，;；]+/).map(item=>item.trim().toLowerCase()).filter(Boolean);
 const identities=()=>identity?lists(identity):(signed?[prefs.accountProfile?.phone,prefs.accountProfile?.mobile,prefs.accountProfile?.email,prefs.accountProfile?.id,'local-account'].map(value=>String(value||'').trim().toLowerCase()).filter(Boolean):['guest']);
 const user=()=>identities()[0]||'guest';
 const bucket=id=>{let hash=2166136261;for(const c of id)hash=Math.imul(hash^c.charCodeAt(0),16777619);return (hash>>>0)%100};
 const worldHost=location.hostname==='world.shiyubox.com';
 const eligible=()=>{const w=config.world,ids=identities(),black=lists(w.blacklist);if(ids.some(id=>black.includes(id)))return false;if(!w.enabled&&!worldHost)return false;const white=lists(w.whitelist),listed=ids.some(id=>white.includes(id));if(worldHost)return true;if(w.audience==='whitelist')return listed;if(w.audience==='percentage')return listed||bucket(user())<Number(w.percentage);return true};
 const receipt=(kind)=>'shiyu-notice-read:'+user()+':'+kind+':'+String(config[kind]?.revision||'');
 const read=kind=>{try{return localStorage.getItem(receipt(kind))==='yes'}catch{return false}};
 function mark(kind){try{localStorage.setItem(receipt(kind),'yes')}catch{}syncEntry()}
 function modal(title,body,footer){
  if(!dialog){dialog=document.createElement('dialog');dialog.id='shiyu-operations-dialog';dialog.setAttribute('aria-labelledby','shiyu-operations-title');document.body.append(dialog);dialog.addEventListener('close',()=>{clearTimeout(timer);timer=setTimeout(deliver,250)})}
  dialog.innerHTML='<div class="ops-heading"><h2 id="shiyu-operations-title">'+esc(title)+"</h2><button data-ops-close aria-label=\"Close\">×</button></div>"+body+'<div class="ops-actions">'+footer+'</div>';
  dialog.querySelector('[data-ops-close]').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();return dialog;
 }
 function waiting(){modal(config.world.title,"<div class=\"ops-coming-hero\"><strong>Coming Soon</strong><span>COMING SOON</span></div><p class=\"ops-body ops-world-description\">"+esc(config.world.description)+'</p>',"<button class=\"primary\" data-ops-ok>Got It</button>").querySelector('[data-ops-ok]').onclick=()=>dialog.close()}
 function details(kind){const n=config[kind];if(!n?.enabled)return;document.querySelector('.shiyu-update-prompt')?.remove();const d=modal(n.title,'<p class="ops-eyebrow">'+(kind==='announcement'?"Service Notice":"Version "+esc(n.revision))+'</p><p class="ops-body">'+esc(n.body)+'</p>','<button class="primary" data-ops-ok>'+(kind==='announcement'?"Got It":"Try It")+'</button>');d.querySelector('[data-ops-ok]').onclick=()=>{mark(kind);d.close()};if(kind==='announcement'){mark(kind)} }
 function center(){
  const items=['announcement','update'].filter(k=>config[k]?.enabled);const d=modal("Notifications",items.length?'<div class="ops-notice-list">'+items.map(k=>'<button data-ops-details="'+k+'"><span><small>'+(k==='announcement'?"Announcement":"What's New")+(read(k)?" · Read":" · Unread")+'</small><b>'+esc(config[k].title)+'</b></span><span>→</span></button>').join('')+'</div>':"<p class=\"ops-empty\">You're all caught up.</p>",'');d.querySelectorAll('[data-ops-details]').forEach(b=>b.onclick=()=>details(b.dataset.opsDetails));
 }
 function syncEntry(){
  const hidden=!config.world.enabled;document.body.classList.toggle('world-entry-disabled',hidden);
  const menu=document.querySelector('.account-menu');if(menu&&!menu.querySelector('[data-ops-center]')){const b=document.createElement('button');b.type='button';b.dataset.opsCenter='';b.setAttribute('role','menuitem');b.innerHTML=svgIcon('<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>')+"Notifications<span class=\"ops-unread-dot\"></span>";b.onclick=center;const logout=menu.querySelector('[data-account-signout]');logout?menu.insertBefore(b,logout):menu.append(b)}
  const unread=['announcement','update'].some(k=>config[k]?.enabled&&!read(k));document.querySelectorAll('[data-ops-center]').forEach(b=>b.classList.toggle('has-unread',unread));
 }
 const oldHeader=updateHeader;updateHeader=function(){oldHeader();syncEntry()};
 const dismissed=()=>{try{return sessionStorage.getItem(receipt('update')+':later')==='yes'}catch{return false}};
 function deliver(){
  clearTimeout(timer);syncEntry();if(document.hidden||document.querySelector('dialog[open]')){if(config.announcement.enabled||config.update.enabled)timer=setTimeout(deliver,1000);return}
  if(config.announcement.enabled&&!read('announcement')){details('announcement');return}
  if(!config.update.enabled||read('update')||dismissed()||document.querySelector('.shiyu-update-prompt'))return;
  const box=document.createElement('aside');box.className='shiyu-update-prompt';box.setAttribute('aria-label',"Update Notice");box.setAttribute('role','status');box.innerHTML='<span class="ops-update-icon">'+svgIcon('<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>')+"</span><div><small>New version · "+esc(config.update.revision)+'</small><b>'+esc(config.update.title)+"</b><button data-ops-view>View Update →</button></div><button class=\"ops-dismiss\" aria-label=\"Remind Later\">×</button>";document.body.append(box);box.querySelector('[data-ops-view]').onclick=()=>details('update');box.querySelector('.ops-dismiss').onclick=()=>{try{sessionStorage.setItem(receipt('update')+':later','yes')}catch{}box.remove()};
 }
 function normalize(value){const notice=n=>({enabled:!!n?.enabled,revision:String(n?.revision||'').slice(0,40),title:String(n?.title||'').slice(0,160),body:String(n?.body||'').slice(0,12000)});const w=value?.world||{};return {world:{...empty.world,appearance:normalizeAppearance(w.appearance),enabled:w.enabled===true,audience:w.audience==='whitelist'||w.audience==='percentage'?w.audience:'all',percentage:Math.min(100,Math.max(0,Number(w.percentage)||0)),whitelist:String(w.whitelist||'').slice(0,30000),blacklist:String(w.blacklist||'').slice(0,30000),title:String(w.title||empty.world.title).slice(0,60),description:String(w.description||empty.world.description).slice(0,1000)},announcement:notice(value?.announcement),update:notice(value?.update),platformCreators:Array.isArray(value?.platformCreators)?value.platformCreators:[]}}
 function publish(){syncEntry();deliver();dispatchEvent(new CustomEvent('shiyu-operations-config',{detail:{worldEnabled:config.world.enabled,platformCreators:config.platformCreators}}))}
 async function loadPublished(force=false){
  if(token&&!force)return;if(loadingPublished)return loadingPublished;
  loadingPublished=fetch('/api/shiyu/operations',{cache:'no-store'}).then(async response=>{const value=await response.json();if(!response.ok)throw new Error(value?.message||"Couldn't load settings");const responseI18n=await fetch('/api/shiyu/i18n/public',{cache:'no-store'});const translated=responseI18n.ok?await responseI18n.json():{notices:{}};const locale=window.ShiyuLanguage?.locale||window.SHIYU_LOCALE_STATE?.locale||'zh-CN';const localizedNotice=kind=>{const n=translated.notices?.[kind],text=n?.translations?.[locale];return text?{...n,...text}:{enabled:false}};config=normalize({world:value.world,platformCreators:value.platformCreators,announcement:localizedNotice('announcement'),update:localizedNotice('update')})}).catch(()=>{config=normalize(empty)}).finally(()=>{loadingPublished=null;publish()});
  return loadingPublished;
 }
 addEventListener('message',event=>{
  if(!token||event.source!==window.opener||event.origin!=='http://127.0.0.1:5175'||event.data?.type!=='shiyu-operations-preview'||event.data?.token!==token)return;
  previewReceived=true;
  config=normalize(event.data.draft);identity=String(event.data.identity||'preview-user-001');previewKind=event.data.kind;
  if(previewKind==='announcement'||previewKind==='update'){config[previewKind].enabled=true;const other=previewKind==='announcement'?'update':'announcement';config[other].enabled=false;try{localStorage.removeItem(receipt(previewKind));sessionStorage.removeItem(receipt('update')+':later')}catch{}}
  try{sessionStorage.setItem(key,JSON.stringify({token,config,identity,kind:previewKind}))}catch{}
  publish();
 });
 window.ShiyuOperations=Object.freeze({enterWorld:()=>{if(eligible())return true;if(!config.world.enabled)return false;waiting();return false},center,worldAppearance:()=>normalizeAppearance(config.world.appearance)});
 document.addEventListener('click',event=>{if(event.target.closest('#world-page [data-ops-center]'))center()});
 addEventListener('focus',()=>{if(token)deliver();else void loadPublished()});document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(token)deliver();else void loadPublished()}});
 setTimeout(()=>{syncEntry();if(token){deliver();if(window.opener)window.opener.postMessage({type:'shiyu-operations-ready',token},'http://127.0.0.1:5175');setTimeout(()=>{if(!previewReceived)void loadPublished(true)},500)}else void loadPublished()},0);
})();
