 function collectionPage(c){return backButton('resources')+`<section class="world-detail-hero" data-tone="${e(c.tone)}"><span class="world-detail-symbol">${icon(c.icon)}</span><div><span class="world-kicker">${e(c.source)} · ${e(topicLabel(c.topic))}</span><h1>${e(c.title)}</h1><p>${e(c.subtitle)}</p></div>${followButton(c.id)}</section><div class="world-detail-layout"><section><div class="world-editor-note"><h2>从这里开始</h2><p>${e(c.note)}</p></div>${heading("这个合集里有什么",c.resourceIds.length+" 个资源 · 访问原站或收藏到稍后整理")}<div class="world-resource-grid world-detail-resources">${c.resourceIds.map(resource).filter(Boolean).map(resourceCard).join('')}</div></section><aside class="world-aside"><span class="world-kicker">留在自己的日常里</span><h3>喜欢的，慢慢收起来</h3><p>收藏单个网址，放进自己的稍后整理；关注合集，方便下次回来继续看。</p><small>当前关注记录保存在本机。</small>${enabled('creators')&&c.author?`<button class="world-text-button" data-w-open="creator" data-w-id="slow">${e(c.author)} ${icon('arrow')}</button>`:''}</aside></div>`}
 function routePage(r){const done=mine().progress[r.id]||[];return backButton('learning')+`<section class="world-detail-hero"><span class="world-detail-symbol">${icon(r.icon)}</span><div><span class="world-kicker">${r.level} · ${r.steps.length} 个步骤</span><h1>${e(r.title)}</h1><p>${e(r.desc)}</p></div></section><div class="world-detail-layout"><section class="world-steps">${r.steps.map((s,i)=>{const link=resource(s.resource);return `<article class="world-step"><span class="world-step-number">${String(i+1).padStart(2,'0')}</span><div><h2>${e(s.title)}</h2><p>${e(s.desc)}</p><a class="world-text-button" href="${e(urlSafe(link.url))}" target="_blank" rel="noopener noreferrer">前往 ${e(link.name)} ${icon('external')}</a></div><label class="world-complete"><input type="checkbox" data-w-step="${i}" ${done.includes(i)?'checked':''}><span>已完成</span></label></article>`}).join('')}</section><aside class="world-aside"><span class="world-kicker">我的学习进度</span><h3 data-w-progress-label>${done.length} / ${r.steps.length} 步已完成</h3><progress value="${done.length}" max="${r.steps.length}" aria-label="学习完成进度"></progress><p>按照自己的节奏来。完成一小步，就做一个标记。</p><small>进度保存在本机。外部视频和课程的开放范围以原站为准。</small></aside></div>`}
