 function updateMode(){
  if(!root)return;
  const mode=document.body.dataset.dark==='true'?'dark':'light',palette=window.ShiyuOperations.worldAppearance();
  const background=palette[mode+'Background'],accent=palette[mode+'Accent'];
  const rgb=background.slice(1).match(/../g).map(value=>parseInt(value,16)/255).map(value=>value<=.04045?value/12.92:((value+.055)/1.055)**2.4);
  const dark=rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722<.3;
  root.dataset.mode=mode;
  const colors={bg:background,accent,'control-accent':accent,ink:dark?'#f3eadb':'#362d24',muted:`color-mix(in srgb,${dark?'#f3eadb':'#362d24'} 72%,${background})`,surface:`color-mix(in srgb,${background} ${dark?'94%':'45%'},#fff)`,soft:`color-mix(in srgb,${background} 86%,${accent})`,'world-line':`color-mix(in srgb,${background} 78%,${dark?'#fff':'#362d24'})`,'world-art':`color-mix(in srgb,${background} 88%,${accent})`};
  for(const [key,value] of Object.entries(colors)){
   root.style.setProperty('--'+key,value);
   // These controls live outside the world section; scope their palette to world mode.
   document.body.style.setProperty('--world-page-'+key,value);
  }
 }
 new MutationObserver(updateMode).observe(document.body,{attributes:true,attributeFilter:['data-dark']});
