      inboxCount: id ? (value.prefs?.extensionInbox || []).length : 0,
      spaces: id ? (value.data || []).map(s => ({ id: s.id, name: s.name, scenes: s.scenes.map(c => ({ id: c.id, name: c.name, groups: c.groups.map(g => ({ id: g.id, name: g.name })) })) })) : [] };
  }
